def preencher_dados_existentes(apps, schema_editor):
    Conversa = apps.get_model("crm", "ConversaWhatsApp")
    Mensagem = apps.get_model("crm", "MensagemWhatsApp")
    Mensagem.objects.filter(direcao="saida").update(status="enviada")
    for conversa in Conversa.objects.all().iterator():
        ultima = Mensagem.objects.filter(conversa=conversa).order_by("-criada_em").first()
        entrada = Mensagem.objects.filter(conversa=conversa, direcao="entrada").order_by("-criada_em").first()
        if not ultima:
            continue
        texto = (ultima.texto or "").replace("\n", " ")
        if ultima.direcao == "saida":
            texto = f"Você: {texto}"
        conversa.ultima_mensagem_em = ultima.criada_em
        conversa.ultima_mensagem_texto = texto[:255]
        conversa.ultima_entrada_em = entrada.criada_em if entrada else None
        conversa.save(update_fields=["ultima_mensagem_em", "ultima_mensagem_texto", "ultima_entrada_em"])


